import pathlib,shutil,importlib.util,subprocess,json,datetime,hashlib
root=pathlib.Path('products/services/open-software-tenders')
page=root/'refresh-20261114/live-preview.html'
result={'observed_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'page_exists':page.is_file(),'executables':{},'python_drivers':{},'node_drivers':{},'browser_execution_performed':False}
if page.is_file(): result['page_sha256']=hashlib.sha256(page.read_bytes()).hexdigest()
for name in ['chromium','chromium-browser','google-chrome','firefox','node']:
 p=shutil.which(name)
 result['executables'][name]=p
 if p and name!='node':
  try:
   r=subprocess.run([p,'--version'],capture_output=True,text=True,timeout=10)
   result.setdefault('versions',{})[name]={'returncode':r.returncode,'stdout':r.stdout[:1000],'stderr':r.stderr[:1000]}
  except Exception as e: result.setdefault('versions',{})[name]={'error':str(e)}
for name in ['playwright','selenium']:
 result['python_drivers'][name]=importlib.util.find_spec(name) is not None
if shutil.which('node'):
 for name in ['playwright','puppeteer','@playwright/test']:
  r=subprocess.run(['node','-e','try { console.log(require.resolve(process.argv[1])); } catch(e) { process.exit(2); }',name],capture_output=True,text=True,timeout=10)
  result['node_drivers'][name]={'available':r.returncode==0,'resolved':r.stdout.strip()}
result['limits']='Installed-program discovery only; no browser execution, isolation, customer use, demand or revenue established. No installation or networking performed.'
out=root/'browser-delivery/installed-prerequisites.json'
out.parent.mkdir(parents=True,exist_ok=True)
out.write_text(json.dumps(result,indent=2)+'\n')
print(out.read_text())
